await invalid("lc-soglasovanie-g-zveno.html", {"bw": "20", "bw_unit": "1000000.0"}, "Требуемая полоса должна быть меньше 2f");
await invalid("lc-soglasovanie-g-zveno.html", {"bw": "x"}, "Требуемая полоса — число");

// Структурные проверки партии №7 (А): запрещённые формы вердикта, карточка источника, реестр, каталог, видимость
// полей по режиму (правило 7), ссылки на соседние страницы вместо дублирования, атрибуция источников и пометки «не подтверждено»,
// необязательные поля пустые — результат остаётся полезным и без прочерков вместо чисел.
{
  kind = "structural";
  const batch7a = ["ksv-otrazhenie", "volnovoe-soprotivlenie-linii", "poteri-v-koaksialnom-kabele", "lc-soglasovanie-g-zveno"];
  const read = file => fs.readFileSync(path.join(sourceDir, file), "utf8");
  const visible = file => read(file).replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ");
  const registry = read("ENGINEERING_AUDIT.md");
  const catalog = read("index.html");
  for (const slug of batch7a) {
    const html = read(`${slug}.html`);
    const text = visible(`${slug}.html`);
    const script = html.match(/<script>([\s\S]*?)<\/script>\s*<\/body>/)?.[1] ?? "";
    check(!/проходит|безопасн|соответствует норм/i.test(text) && !/проходит|безопасн|соответствует норм/i.test(script),
      `${slug}: запрещённые слова «проходит», «безопасно», «соответствует нормам»`);
    const card = html.match(/<section class="src">([\s\S]*?)<\/section>/)?.[1] ?? "";
    check(card.includes("Оценка, не нормативный вердикт") && card.includes("Границы применимости") && card.includes("Допущения")
      && card.includes("Редакция") && /обращение 13\.11\.2026/.test(card) && !/Проверил:/.test(card),
      `${slug}: карточка источника без статуса, допущений, границ, редакции или даты обращения — либо с выдуманным проверяющим`);
    check(registry.includes(`\`${slug}\``), `ENGINEERING_AUDIT.md: нет записи о ${slug}`);
    check(catalog.includes(`href="${slug}.html"`), `index.html: ${slug} нет в каталоге`);
    // Нет экспоненты и прочерков вместо чисел в тексте страницы с результатами по умолчанию и в скрипте нет «Infinity» в выводе строк
    check(!/\bNaN\b|undefined/.test(text), `${slug}: в видимом тексте NaN или undefined`);
  }
  const state = async (file, values) => {
    const dom = await load(file); const d = dom.window.document;
    for (const [id, v] of Object.entries(values)) { const el = d.getElementById(id); el.value = v; el.dispatchEvent(new dom.window.Event("change", { bubbles: true })); }
    const hidden = new Set([...d.querySelectorAll(".f")].filter(f => f.style.display === "none").map(f => f.id.replace(/^f_/, "")));
    dom.window.close(); return hidden;
  };
  let hs = await state("ksv-otrazhenie.html", {});
  check(hs.has("s") && hs.has("rl") && !hs.has("r") && !hs.has("x") && !hs.has("slim"), "ksv-otrazhenie: в режиме нагрузки видны R, X и допустимый КСВ, скрыты КСВ и RL");
  hs = await state("ksv-otrazhenie.html", { mode: "vswr" });
  check(!hs.has("s") && hs.has("rl") && hs.has("r") && hs.has("x") && hs.has("slim"), "ksv-otrazhenie: в режиме КСВ виден КСВ, скрыты R, X, RL и допустимый КСВ");
  hs = await state("ksv-otrazhenie.html", { mode: "rl" });
  check(!hs.has("rl") && hs.has("s") && hs.has("r") && hs.has("x") && !hs.has("slim"), "ksv-otrazhenie: в режиме RL виден RL и допустимый КСВ, скрыты R, X и КСВ");
  hs = await state("volnovoe-soprotivlenie-linii.html", {});
  check(!hs.has("cD") && !hs.has("cd") && hs.has("tD") && hs.has("td") && hs.has("mW") && hs.has("mh") && hs.has("z0t"), "volnovoe-soprotivlenie-linii: для коаксиала видны D и d, скрыты размеры других линий и Z0");
  hs = await state("volnovoe-soprotivlenie-linii.html", { ty: "twin" });
  check(hs.has("cD") && hs.has("cd") && !hs.has("tD") && !hs.has("td") && hs.has("mW") && hs.has("mh"), "volnovoe-soprotivlenie-linii: для двухпроводной линии видны D и d");
  hs = await state("volnovoe-soprotivlenie-linii.html", { ty: "strip" });
  check(hs.has("cD") && hs.has("cd") && hs.has("tD") && hs.has("td") && !hs.has("mW") && !hs.has("mh"), "volnovoe-soprotivlenie-linii: для микрополоска видны W и h");
  hs = await state("volnovoe-soprotivlenie-linii.html", { mode: "inv", ty: "strip" });
  check(hs.has("mW") && !hs.has("mh") && !hs.has("z0t") && hs.has("cD"), "volnovoe-soprotivlenie-linii: в обратном режиме микрополоска скрыта ширина W, виден Z0");
  hs = await state("volnovoe-soprotivlenie-linii.html", { mode: "inv" });
  check(!hs.has("cD") && hs.has("cd") && !hs.has("z0t"), "volnovoe-soprotivlenie-linii: в обратном режиме коаксиала скрыт диаметр жилы d");
  hs = await state("poteri-v-koaksialnom-kabele.html", {});
  check(!hs.has("f0") && !hs.has("a0") && !hs.has("tg") && !hs.has("er") && hs.has("f1") && hs.has("a1") && hs.has("f2") && hs.has("a2"), "poteri-v-koaksialnom-kabele: в режиме одной частоты видны f0, α0, tgδ, εr, скрыты f1, f2");
  hs = await state("poteri-v-koaksialnom-kabele.html", { mode: "two" });
  check(hs.has("f0") && hs.has("a0") && hs.has("tg") && hs.has("er") && !hs.has("f1") && !hs.has("a1") && !hs.has("f2") && !hs.has("a2"), "poteri-v-koaksialnom-kabele: в режиме двух частот видны f1, f2, скрыты f0, tgδ, εr");
  // Не подставлять паспортные величины: поля пустые, а значение по умолчанию на странице не появляется
  {
    const dom = await load("poteri-v-koaksialnom-kabele.html"); const d = dom.window.document;
    check(d.getElementById("f0").value === "" && d.getElementById("a0").value === "" && d.getElementById("f1").value === "" && d.getElementById("a1").value === ""
      && d.getElementById("f2").value === "" && d.getElementById("a2").value === "" && d.getElementById("tg").value === "" && d.getElementById("er").value === "",
      "poteri-v-koaksialnom-kabele: паспортные поля подставлены по умолчанию");
    dom.window.close();
  }
  hs = await state("lc-soglasovanie-g-zveno.html", {});
  check(!hs.has("big") && !hs.has("var") && !hs.has("qc") && !hs.has("bw"), "lc-soglasovanie-g-zveno: оба переключателя и необязательные поля видны");
  // Необязательные поля пустые — результат остаётся полезным: есть статус, нет прочерков вместо чисел
  for (const [file, values] of [["ksv-otrazhenie.html", {}], ["ksv-otrazhenie.html", { mode: "vswr" }], ["ksv-otrazhenie.html", { mode: "rl", pin: "", slim: "" }],
    ["volnovoe-soprotivlenie-linii.html", {}], ["volnovoe-soprotivlenie-linii.html", { ty: "twin", f: "" }], ["volnovoe-soprotivlenie-linii.html", { ty: "strip", mode: "inv", f: "" }],
    ["poteri-v-koaksialnom-kabele.html", { f0: "100", a0: "1.9", au: "ft100", pin: "", tol: "", bud: "", tg: "", er: "" }],
    ["poteri-v-koaksialnom-kabele.html", { mode: "two", f1: "10", a1: "1.1", f2: "100", a2: "3.8", au: "ft100", pin: "" }],
    ["lc-soglasovanie-g-zveno.html", {}], ["lc-soglasovanie-g-zveno.html", { qc: "", bw: "", big: "load", var: "hp" }]]) {
    const dom = await load(file); const d = dom.window.document;
    for (const [id, v] of Object.entries(values)) { const el = d.getElementById(id); el.value = v; el.dispatchEvent(new dom.window.Event("change", { bubbles: true })); }
    d.getElementById("go").click();
    const res = d.getElementById("res").textContent.replace(/\s+/g, " ");
    check(/Статус/.test(res) && !/\S—/.test(res) && !/NaN|undefined|Infinity|·10\^/.test(res),
      `${file}: при пустых необязательных полях ${JSON.stringify(values)} нет статуса или есть прочерк вместо числа: «${res.slice(0, 200)}»`);
    dom.window.close();
  }
  // Каждый необязательный ввод меняет результат: без него строк нет, с ним есть (правило 7)
  const optional = async (file, base, extra, markers, absent) => {
    for (const [fileV, values, wantPresent] of [[file, base, false], [file, { ...base, ...extra }, true]]) {
      const dom = await load(fileV); const d = dom.window.document;
      for (const [id, v] of Object.entries(values)) { const el = d.getElementById(id); el.value = v; el.dispatchEvent(new dom.window.Event("change", { bubbles: true })); }
      d.getElementById("go").click();
      const res = d.getElementById("res").textContent.replace(/\s+/g, " ");
      for (const m of markers) check(res.includes(m) === wantPresent, `${file}: необязательный ввод ${JSON.stringify(extra)} ${wantPresent ? "не добавил" : "лишний"} фрагмент «${m}»`);
      dom.window.close();
    }
  };
  await optional("ksv-otrazhenie.html", {}, { pin: "10" }, ["Мощность в нагрузке", "Отражённая мощность при падающей"]);
  await optional("ksv-otrazhenie.html", {}, { slim: "2" }, ["Оценка: КСВ 1,5 не больше допустимого 2"]);
  await optional("volnovoe-soprotivlenie-linii.html", {}, { f: "100" }, ["Длина волны в линии", "Четверть волны"]);
  const pb = { f0: "100", a0: "1.9", au: "ft100", f: "145", len: "20", pin: "" };
  await optional("poteri-v-koaksialnom-kabele.html", pb, { pin: "100" }, ["Мощность на выходе", "Рассеивается в кабеле"]);
  await optional("poteri-v-koaksialnom-kabele.html", pb, { tol: "10" }, ["Потери с учётом разброса", "КПД с учётом разброса"]);
  await optional("poteri-v-koaksialnom-kabele.html", pb, { bud: "3" }, ["Допустимые потери в линии"]);
  await optional("poteri-v-koaksialnom-kabele.html", pb, { tg: "0.0003", er: "2.25" }, ["Потери в диэлектрике k2: дБ/м на МГц0,0000"]);
  await optional("lc-soglasovanie-g-zveno.html", {}, { qc: "50" }, ["Потери на катушке при Q катушки 50"]);
  await optional("lc-soglasovanie-g-zveno.html", {}, { bw: "4" }, ["перекрывает требуемую полосу 4 МГц"]);
  // Не дублировать соседние страницы, а ссылаться на них.
  const links = { "ksv-otrazhenie": ["volnovoe-soprotivlenie-linii", "lc-soglasovanie-g-zveno", "poteri-v-koaksialnom-kabele", "decibel"],
    "volnovoe-soprotivlenie-linii": ["ksv-otrazhenie", "lc-soglasovanie-g-zveno", "poteri-v-koaksialnom-kabele"],
    "poteri-v-koaksialnom-kabele": ["volnovoe-soprotivlenie-linii", "ksv-otrazhenie", "decibel", "attenyuator"],
    "lc-soglasovanie-g-zveno": ["ksv-otrazhenie", "volnovoe-soprotivlenie-linii", "rezonans-lc", "lc-filtr-raschet"] };
  for (const [from, list] of Object.entries(links)) {
    const article = read(`${from}.html`).match(/<p class="intro">[\s\S]*?<section class="related">/)?.[0] ?? "";
    for (const to of list) check(article.includes(`href="${to}.html"`), `${from}: в тексте нет ссылки на ${to}`);
  }
  // Входящие ссылки внутри партии: страницы связаны друг с другом (кольцо), поэтому не сироты
  const ring = [["ksv-otrazhenie", "volnovoe-soprotivlenie-linii"], ["ksv-otrazhenie", "lc-soglasovanie-g-zveno"], ["ksv-otrazhenie", "poteri-v-koaksialnom-kabele"],
    ["volnovoe-soprotivlenie-linii", "ksv-otrazhenie"], ["poteri-v-koaksialnom-kabele", "ksv-otrazhenie"], ["lc-soglasovanie-g-zveno", "ksv-otrazhenie"]];
  for (const [from, to] of ring) {
    const block = read(`${from}.html`).match(/<section class="related">([\s\S]*?)<\/section>/)?.[1] ?? "";
    check(block.includes(`href="${to}.html"`), `${from}: в «Смотрите также» нет ссылки на ${to}`);
  }
  // Атрибуция: первоисточник, оговорки о том, что не подтверждено, выводы на странице
  const k = visible("ksv-otrazhenie.html");
  check(/Pozar|Позара/.test(k) && /Utah/.test(k) && /выведен/.test(k) && /Γ = \(ZL − Z0\)\/\(ZL \+ Z0\)/.test(k) && /не сверены/.test(k) && /не ограничен/.test(k),
    "ksv-otrazhenie: нет атрибуции Позара и курса Utah, вывода Γ, оговорки о несверенных номерах разделов или слова «не ограничен»");
  const v = visible("volnovoe-soprotivlenie-linii.html");
  check(/Hammerstad/.test(v) && /Qucs/.test(v) && /CODATA/.test(v) && /зарядов-нитей/.test(v) && /0,2 %/.test(v) && /0,01 %/.test(v) && /0,03 %/.test(v)
    && /не включая 128/.test(v) && /оригинал[^.]{0,40}не открывался/.test(v) && /толщин[^.]{0,80}не использ/.test(v) && /вопрос к ручной сверке/.test(v),
    "volnovoe-soprotivlenie-linii: нет атрибуции Хаммерстада–Йенсена и Qucs, заявленных точностей, области применимости, оговорки о неоткрытом оригинале и неподтверждённой поправке на толщину");
  const p = visible("poteri-v-koaksialnom-kabele.html");
  check(/Belden/.test(p) && /редакцию (нужно )?сверить/.test(p) && /PA3FWM/.test(p) && /не подставля/.test(p) && /экстраполяц/.test(p) && /отрицательн/.test(p) && /вырожден/.test(p),
    "poteri-v-koaksialnom-kabele: нет атрибуции Belden с пометкой «редакцию сверить», заметки PA3FWM, отказа подставлять паспортные величины, экстраполяции, вырожденности и отрицательных коэффициентов");
  const l = visible("lc-soglasovanie-g-zveno.html");
  check(/Steer/.test(l) && /Pozar|Позара/.test(l) && /ARRL/.test(l) && /подтвердить не удалось|не подтверждено|не найден/.test(l) && /2f\/Q/.test(l) && /Q\/2/.test(l),
    "lc-soglasovanie-g-zveno: нет атрибуции Позара и Steer, оговорки о неподтверждённом ARRL Handbook и разбора правила f/Q против 2f/Q");
}
